import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水火既济","description":"周易折中 - 水火既济","frontmatter":{"title":"水火既济","description":"周易折中 - 水火既济"},"headers":[],"relativePath":"zh/classics/zhezhong/069.md","filePath":"zh/classics/zhezhong/069.md"}'),h={name:"zh/classics/zhezhong/069.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="水火既济" tabindex="-1">水火既济 <a class="header-anchor" href="#水火既济" aria-label="Permalink to “水火既济”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈既济序卦〉：“有过物者必济，故受之以既济。能过于物，必可以济，故小过之后受之以既济也。为卦水在火上，水火相交则为用矣，各当其用，故为既济。天下万事已济之时也。”</p><p>既济：亨，小利贞，初吉终乱。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>既济，事之既成也。为卦水火相交，各得其用，六爻之位，各得其正，故为既济。亨小，当为小亨。大抵此卦及六爻占辞皆有警戒之意，时当然也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>既济之时，大者既已亨矣，小者尚有未亨也。虽既济之时，不能无小未亨也。“小字在下”，语当然也。若言小亨，则为亨之小也。利贞，处既济之时，利在贞固以守之也。初吉，方济之时也。终乱，济极则反也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：人皆不能居安思危，慎终如始，故戒以今日既济之初，虽皆获吉，若不进德修业，至于终极，则危乱及之。</p></li><li><p>谷氏家杰曰：不曰“小亨”而曰“亨小”，言所亨者其小事也。</p></li><li><p>吴氏曰：既济之时，刚柔正则体立，水火交则用行。体立用行，所以为既济也。案天地交为泰，不交则为否；水火交为既济，不交则为未济。以治乱之运推之，泰、否其两端也，既济、未济其交际也。既济当在泰之后而否之先，未济当在泰之先而否之后。泰犹夏也，否犹冬也，未济犹春也，既济犹秋也。故先天之图，乾坤居南北，是其两端也；离坎居东西，是其交际也。既济之义不如泰者，为其泰而将否也；未济之义优于否者，为其否而将泰也。是以既济彖辞曰“初吉终乱”，即泰城复于隍之戒；未济彖辞曰“汔济濡其尾，无攸利”，即否其亡其亡之心。</p></li></ul><p>象曰：水在火上，既济；君子以思患而豫防之</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>水火既交，各得其用，为既济。时当既济，唯虑患害之生，故思而豫防，使不至于患也。自古天下既济而致祸乱者，盖不能思患而豫防也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏申子曰 ：既济虽非有患之时，患每生于既济之后。君子思此而豫防之，则可以保其初吉而无终乱之忧矣。</p></li><li><p>龚氏焕曰 ：水上火下虽相为用，然水决则火灭，火炎则水涸。相交之中，相害之机伏焉。故君子思患而豫防之。能防在乎豫，能豫在乎思。</p></li></ul><p>彖曰：既济 亨，小者亨也</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>济下疑脱小字</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏铨曰：国家当极盛时，纵有好处都只是寻常事，所以说“小者亨”。案：“亨小”之义，陆氏说善。既济之时，自然事事亨通，然特其小者尔。圣人之制治保邦也，制度之立、纲纪之修以为小，而精神之运、心术之动以为大。故屯难之时而大亨者，以其动乎险中不敢安宁也；既济之时而亨小者，以其已安已治，四达不悖也。彖所以言“初吉终乱”者以此，象所以言“思患豫防”者亦以此。</li></ul><p>利贞，刚柔正而位当也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体言</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>既济之时，大者固已亨矣，唯有小者未亨也。时既济矣，固宜贞固以守之。卦才刚柔正当其位，当位者其常也，乃正固之义，利于如是之贞也。阴阳各得正位，所以为既济也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：三刚三柔皆正而位皆当，六十四卦之中独此一卦而已，故特赞之也。</li></ul><p>初吉，柔得中也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>指六二</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>二以柔顺文明而得中，故能成既济之功。二居下体，方济之初也，而又善处，是以吉也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰：既济柔得中，在下卦则初吉而终乱，以文明已过而坎险继之也。未济柔得中，在上卦则始未济而终亨，以出乎坎险而正当文明也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>凡易义以刚中为善，而既未济皆善柔中者。既济以内卦为主，至外卦则向乎未济矣；未济亦以内卦为主，至外卦则向乎既济矣。亦犹泰之善在二而否之善在五。</p><p>终止则乱，其道穷也</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>天下之事，不进则退，无一定之理。济之终不进而止矣，无常止也，衰乱至矣，盖其道已穷极也。九五之才非不善也，时极道穷，理当必变也。圣人至此奈何曰：唯圣人为能通其变于未穷，不使至于极也。尧舜是也，故有终而无乱。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>侯氏行果曰：由止故物乱而穷也。《干凿度》曰：“既济未济者，所以明戒慎全王道也。”</p></li><li><p>胡氏瑗曰：天下久治则人苟安，万务易坠，祸患不警。故持盈守成之道，当须至兢至慎，然后可以久济。苟止于逸乐，不自省惧，以为终安，乱斯至矣。此圣人深戒之辞。</p></li><li><p>张氏清子曰：卦曰“终乱”，而彖曰“终止则乱”，非终之能乱也，于其终而有止心，此乱之所由生也。</p></li><li><p>俞氏琰曰：人之常情，处无事则止心生，止则怠，怠则有患而不为之防，此所以乱也。当知“终止则乱”，不止则不乱也。</p></li></ul><p>初九：曳其轮，濡其尾，无咎。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>轮在下，尾在后，初之象也。曳轮则车不前，濡尾则狐不济。既济之初，谨戒如是无咎之道。占者如是，则无咎矣。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初以阳居下，上应于四，又火体，其进之志锐也。然时既济矣，进不已则及于悔咎，故曳其轮，濡其尾，乃得无咎。轮所以行，倒曳之使不进也；兽之涉水，必掲其尾，濡其尾则不能济。方既济之初，能止其进，乃得无咎。不知已，则至于咎也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏简曰：既济之初，以濡尾而曳轮，见其用力之难也。虽濡其尾，于义何咎。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>爻之文意，李氏得之。盖曳轮者，有心于曳之也；濡尾者，非有心于濡之也。当济之时，众皆竞济，故有濡尾之患。惟能曳其轮，则虽濡其尾而可及止也。观夫子象传可知。</p><p>象曰：曳其轮，义无咎也</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>既济之初而能止其进，则不至于极，其义自无咎也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>徐氏在汉曰 ：初当方济之始而曳其济险之轮，控制在我，则义无不济。此所以濡其尾而无咎，象故归重于曳其轮也。</li></ul><p>六二：妇丧其茀，勿逐，七日得。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>二以文明中正之德，上应九五刚阳中正之君，宜得行其志。而九五居既济之时，不能下贤以行其道，故二有“妇丧其茀”之象。茀，妇车之蔽，言失其所以行也。然中正之道不可终废，时过则行矣。故又有“勿逐而自得之”戒。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二以文明中正之德，上应九五刚阳中正之君，宜得行其志也。然五既得尊位，时已既济，无复进而有为矣，则于在下贤才岂有求用之意？故二不得遂其行也。自古既济而能用人者鲜矣，以唐太宗之用贤尚怠于终，况其下者乎？于斯时也，则刚中反为中满，坎离乃为相戾矣。人能识时知变，则可以言易矣。二阴也，故以妇言。茀，妇人出门以自蔽者也，丧其茀则不可行矣。二不为五之求用，则不得行，如妇之丧茀也。然中正之道岂可废也？时过则行矣。逐者，从物也，从物则失其素守，故戒勿逐。自守不失，则七日当复得也。卦有六位，七则变矣，“七日得”谓时变也。虽不为上所用，中正之道无终废之理，不得行于今，必行于异时也。圣人之劝戒深矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：丧茀，失其在外者；逐，则失其在我者矣。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>初二居下位，故皆取君子欲济时而未得济为义。轮者，车之所以行路也；茀者，车之所以蔽门也。初之时，未可以行也，故曰“曳其轮”。二可以行矣，而不苟于行，苟丧其茀，亦不行也。夫义路也，礼门也。义不可则不行，礼不备则亦不苟于行也。二有应而曰“丧其茀”者，既未济卦义以上下体之交为济，二犹居下体之中，故也。</p><p>象曰：七日得以中道也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>中正之道，虽不为时所用，然无终不行之理。故丧茀七日，当复得。谓自守其中，异时必行也。不失其中，则正矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：二居下卦之中，以中感中，得其正应，故终必相孚也。</li></ul><p>九三：高宗伐鬼方，三年克之，小人勿用。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>既济之时，以刚居刚，高宗伐鬼方之象也。三年克之，言其久而后克，戒占者不可轻动之意。小人勿用，占法与师上六同。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>九三当既济之时，以刚居刚，用刚之至也。既济而用刚，如是乃高宗伐鬼方之事。高宗必商之高宗，天下之事既济而远征暴乱也。威武可及，而以救民为心，乃王者之事也。惟圣贤之君则可，若骋威武、忿不服、贪土地，则残民肆欲也。故戒不可用小人，小人为之则以贪忿私意也。非贪忿则莫肯为也。三年克之，见其劳惫之甚。圣人因九三当既济而用刚，发此义以示人为法为戒，岂浅见所能及也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>沈氏该曰：既济初吉，锐于始也；终止则乱，怠于终也。中兴之业既就，远方之伐既成，而使小人预于其间，贪功逞欲，惫民不息，则必以乱终。不可不戒，是以小人勿用也。</p></li><li><p>龚氏焕曰：三言“克鬼方”，则事已济矣；“三年”，言其济之难。小人勿用，欲保其济也。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>既济、未济皆以高宗言者，高宗为商中兴之君，振衰拨乱，自未济而既济者也。既济于三言之者，卦为既济，至于内卦之终，则已济矣，故曰“克之者”为已然之辞。未济于四言之者，卦为未济，则至外卦之初方图济也，故曰“震用者”为方然之辞。既济之后，则当思患而豫防之，故“小人勿用”与师之戒同。</p><p>象曰：三年克之，惫也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>言惫以见其事之至难。在高宗为之，则可；无高宗之心，则贪忿以殃民也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>言惫以见成功之非易。如人之疾病而以毒药攻去之者，其元气亦秏伤矣。苟无休养之方以复元气，则又大病之根也。</p><p>六四：𦈡有衣袽，终日戒。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>既济之时，以柔居柔，能豫备而戒惧者也，故其象如此。程子曰：“𦈡”当作“濡”，衣袽所以塞舟之罅漏。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四在济卦而水体，故取舟为义。四近君之位，当其任者也。当既济之时，以防患虑变为急。“𦈡”当作“濡”，谓渗漏也。舟有罅漏，则塞以衣袽，有衣袽以备濡漏，又终日戒惧不怠，虑患当如是也。不言吉，方免于患也。既济之时，免患则足矣，岂复有加也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：衣袽所以备舟隙也。卦以济为事，故取于舟。</p></li><li><p>郭氏忠孝曰：既济思患豫防，而四又居多惧之地，是以有“𦈡有衣袽”之戒。勿以既济而忘未济之难也。终日者，言无怠时也。</p></li><li><p>胡氏炳文曰：乘舟者不可以无“𦈡”而忘衣袽，亦不可谓衣袽已备，遂恝然不知戒。水浸至而不知，则虽有衣袽不及施矣。备患之具不失于寻常，而虑患之念又不忘于顷刻，此处既济之道。</p></li><li><p>张氏清子曰：六四出离入坎，此济道将革之时也。济道将革，则罅漏必生。四坎体也，故取漏舟为戒。终日戒者，自朝至夕不忘戒备，常若坐敝舟而水骤至焉，斯可以免覆溺之患。</p></li></ul><p>备注：明治维新时期，日本易学家高岛吞象在《高岛易断》里描述</p><p>按“繻”为采绘，“袽”为敝衣。四处内外卦之交，出《离》入坎，繻有文明之象，盖取诸《离》；袽为败衣，《坎》为破，盖取诸《坎》。言四当《既济》之盛，衣冠济济，文物声名，焕然一新，然天命靡常，盛倏为衰，新倏成故，若不因时弥缝，曾不几时，立成败坏，犹是绘采之华裳，未几而为敝败之残絮矣，故曰“繻有衣袽。”《既济》，由《乾》《坤》二五相易而来，“终日戒”者，即《乾》“终日乾乾，夕惕若”之意，当《既济》而益励危心，其戒慎无已时也，故曰“终日戒”。《传》释以“有所疑”，《坎》为疑，疑者，未然而忧其或然，亦戒也。“繻”，王弼谓宜作濡，衣袽谓以敝衣塞舟漏也。王弼之解，强从济字取义，谓济必有舟，舟或有漏则濡，濡则敝衣塞之。于爻辞“繻有衣袽”一语，添生枝节，自圆其说，未免矫强。</p><p>象曰：终日戒，有所疑也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>终日戒惧，常疑患之将至也。处既济之时，当畏愼如是也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏简曰 ：终日戒，谓备患之心无时可忘也。</li></ul><p>九五：东邻杀牛，不如西邻之禴祭，实受其福。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>东阳西阴，言九五居尊而时已过，不如六二之在下而始得时也。又当文王与纣之事故，其象占如此。彖辞“初吉终乱”亦此意也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>五中实孚也，二虚中诚也，故皆取祭祀为义。东邻阳也，谓五；西邻阴也，谓二。杀牛盛祭也，禴薄祭也。盛不如薄者，时不同也。二五皆有孚诚中正之德，二在济下尚有进也，故受福；五处济极无所进矣，以至诚中正守之，苟未至于反耳，理无极而终不反者也。已至于极，虽善处无如之何矣。故爻象惟言其时也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰：既济盛极则衰至，君子当思患豫防，持盈以虚，保益以损。六四已有终日之戒矣，而况于五乎？西邻之时，守以损约，故终受福。</p></li><li><p>潘氏士藻曰：五以阳刚中正，当物大丰盛之时，故借东邻祭礼以示警惧。夫祭时为大，苟得矣，则明德馨而黍稷可荐，明信昭而沼毛可羞。是以东邻杀牛，不如西邻之禴祭，实受其福。在于合时，不在物丰也。东西者，彼此之词，不以五与二对言。</p></li><li><p>姚氏舜牧曰：人君当既济时，享治平之盛，骄奢易萌，而诚敬必不足。故圣人借两邻以为训，若曰“东邻杀牛何其盛也，西邻禴祭何其薄也”。然神无常享，享于克诚。彼杀牛者，反不如禴祭者之实受其福。信乎享神者在诚，不在物；保治者以实，不以文。此盖教之以祈天保命之道。</p></li></ul><h3 id="案-站长备注在下" tabindex="-1">案（站长备注在下） <a class="header-anchor" href="#案-站长备注在下" aria-label="Permalink to “案（站长备注在下）”">​</a></h3><p>潘氏、姚氏之说皆是。当受报收功极炽而丰之时，而能行恭敬撙节、退让明礼之事，此其所以受福也。与泰三“于食有福”同，皆就本爻设戒尔。若以西邻为六二，则受福为六二受福，易无此例。</p><p>象曰：东邻杀牛，不如西邻之时也；实受其福，吉大来也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>五之才德非不善，不如二之时也。二在下，有进之时，故中正而孚，则其吉大来，所谓受福也。吉大来者，在既济之时为大来也。亨小初吉是也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰 ：盛不如薄者，时也。五既济无所进，盈则当虚，故曰不如西邻之禴祭。理无极而不反者，既济极矣。五以中正守之，能未至于反而已。</p></li><li><p>王氏申子曰 ：言人君处既济如未济，而后有受福之实。不然，虽极其丰盛而济道衰矣。</p></li><li><p>张氏淸子曰 ：既济之后，唯恐过盛。以祭言之，于斯时也，丰不如约。故东邻不如西邻，牛不如禴。盖祭而得其时，虽禴之薄，实足以受其福，而吉之大来可知矣。</p></li></ul><p>站长备注</p><h3 id="为什么《案》和《本义》相互矛盾" tabindex="-1">为什么《案》和《本义》相互矛盾？ <a class="header-anchor" href="#为什么《案》和《本义》相互矛盾" aria-label="Permalink to “为什么《案》和《本义》相互矛盾？”">​</a></h3><p>《周易折中》里的《案》和《本义》皆为李光地所述，《本义》里大多数是简明扼要的说明本来意义，述而不作；《案》通常为李光地总结和评价《集说》；本篇《案》的意思是，易里面爻辞通常是对本爻而言，而非对其它爻而言，也就是说，这里的叙述很明显不是对二爻而言，而是对五爻本身而言，「受福」和「吉大来」如果都是说二爻，那为何不直接在二爻上注明呢？这么一来五爻的爻辞变得没有意义。</p><h3 id="卦辞「初吉终乱」从何而来" tabindex="-1">卦辞「初吉终乱」从何而来？ <a class="header-anchor" href="#卦辞「初吉终乱」从何而来" aria-label="Permalink to “卦辞「初吉终乱」从何而来？”">​</a></h3><p>卦辞之所以说「初吉终乱」无外乎先离后坎，离新坎旧。《离》为文明、为奢华、为新。《坎》为破败老旧，为俭朴。这也是为什么四爻「繻有衣袽，终日戒」是因为四爻本体《离》，进一步入《坎》。借用高岛吞象的话：繻有文明之象，盖取诸《离》；袽为败衣，《坎》为破，盖取诸《坎》。所以说从大象来去看「君子以思患而豫防之」就是戒言由离入坎，预防由奢华走向破败，是下卦为「奢华」上卦为「破败/俭朴」。</p><h3 id="站长对取爻的质疑" tabindex="-1">站长对取爻的质疑 <a class="header-anchor" href="#站长对取爻的质疑" aria-label="Permalink to “站长对取爻的质疑”">​</a></h3><p>诸位易学家都是从卦辞「初吉终乱」为切入点，认为二爻为「初吉」，五爻为「终乱」。再结合象曰里的「东邻杀牛，不如西邻之时也」。就得出二爻为『东邻/禴祭/薄祭/俭朴』，而五爻为『西邻/杀牛/奢华』。这样虽然紧扣了「初吉终乱」，但是站长认为其他易学家将“初吉终乱”的卦辞概念直接用于爻辞的解释，很容易忽视了爻辞自身的情境和特点。爻辞和卦整体有联系，但是各抒己见，单爻应该独论。按照取象来说：</p><p>离：为 牛 、为东邻；</p><p>坎：为禴祭（薄祭，简约的祭祀）、为实（离虚坎实）、为西邻；</p><p>卦象从离入坎，所以卦辞强调「君子以思患而豫防之」；而从爻来看，谁处奢华自当戒之，谁简约自处自当受福；是戒东邻奢华，不如西邻简约而受福，离“奢”不如坎“俭”。所以卦和爻两者定然是相反的，卦辞「初吉终乱」不能作为解读爻辞里事物的取爻的依据。大意九五俭朴自处且有中正之德，戒言奢而慢，不如俭而敬。</p><h3 id="禴祭的阴阳也可以佐证" tabindex="-1">禴祭的阴阳也可以佐证 <a class="header-anchor" href="#禴祭的阴阳也可以佐证" aria-label="Permalink to “禴祭的阴阳也可以佐证”">​</a></h3><p>&quot;禴祭&quot;（yuè jì），禴古同“礿”，中国夏商两代在春天举行，周代在夏天举行。</p><h2 id="礼记-·-祭统" tabindex="-1">礼记 · 祭统 <a class="header-anchor" href="#礼记-·-祭统" aria-label="Permalink to “礼记 · 祭统”">​</a></h2><p>凡祭有四时：春祭曰礿，夏祭曰禘，秋祭曰尝，冬祭曰烝。礿、禘，阳义也；尝、烝，阴义也。禘者阳之盛也，尝者阴之盛也。故曰：莫重于禘、尝。古者于禘也，发爵赐服，顺阳义也；于尝也，出田邑，发秋政，顺阴义也</p><p>从《礼记 · 祭统》可以看出，禴祭（礿祭）是取自阳义，本身指的是六五这个阳爻，而并非六二阴爻。此证可否定程传「东邻阳也，谓五；西邻阴也，谓二」之说。</p><h3 id="关于禴祭属于薄祭" tabindex="-1">关于禴祭属于薄祭 <a class="header-anchor" href="#关于禴祭属于薄祭" aria-label="Permalink to “关于禴祭属于薄祭”">​</a></h3><p>南北朝时期沈约的《梁三朝雅乐歌》</p><p>雅有洄酌风采苹。(意思：风雅的举止如同回旋的水流轻轻拂过苹草。) 蕴藻之菜非八珍。(意思：内含文采的素菜不是世间的八种珍贵食物。) 涧溪沼沚贵先民。(意思：山涧、溪流、沼地和浅滩，这些都是古代先民所珍视的。) 明信之德感人神。(意思：光明而真诚的德行能够感动人与神。) 譬诸礿祭在西邻。(意思：就像西邻的礿祭，简单而真诚。)</p><p>从沈约的这个诗歌比喻，可以看出禴祭是一种薄祭，是一种简约的祭祀。更多礿祭为薄祭之说，可以参见《礼记》《周礼》等古籍，可窥见一二。</p><p>上六：濡其首，厉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>既济之极，险体之上，而以阴柔处之，为狐渉水而濡其首之象。占者不戒危之道也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>既济之极，固不安而危也。又阴柔处之，而在险体之上。坎为水，济亦取水义，故言其穷至于濡首，危可知也。既济之终而小人处之，其败坏可立而待也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰：物盛则衰，治极必乱，理之常也。上六处既济之终，其道穷极，至于衰乱，如渉险而濡溺其首，是危厉之极也。皆由治不思乱，安不虑危，以至穷极而反于未济也。</p></li><li><p>薛氏温其曰：濡其尾者，有后顾之义；濡其首者，不虑前也。恃以为济，遂至陷没，没而至首，其危可知。历险而不虞患，故曰“乱者有其治者也”。既济终乱，其义见矣。</p></li><li><p>朱氏震曰：以画卦言之，初为始为本，上为终为末；以成卦言之，上为首为前，初为尾为后。</p></li></ul><p>象曰：濡其首，厉，何可久也</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>既济之穷危，至于濡首，其能长久乎？</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏瑗曰 ：既济之终，反于未济，至于濡没其首，故当翻然而警惕，然而改。何可久如此乎？</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>厉未至于凶，特可危尔。知其危而反之，则不至于濡首矣。凡《易》言“何可长”、“何可久”者，自屯上至此爻，皆惕以改悟而不可迷溺之意。</p>',144)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
